// Porous Deep - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// With drilled holes the shading that matters is DEPTH: the inner walls should
// fall away into darkness while the outer shell stays a clean bone white. The
// engine's AO already does most of it; here we add a depth-driven tint plus a
// bright rim on the hole lips, which is what reads as "thin shell" in the photos.
// In scope: pModel, n_model, viewDir_model, mainLight_model.
// Dock colors: u_col1 = shell (light), u_col2 = hole interior (warm dark).

float DENSITY   = 6.0 * E;   // slider E    // MUST match the displacement
float R_MIN     = 0.12;
float R_MAX     = 0.52;
float SIZE_BIAS = 2.2;
float FILL      = 0.85 * F;   // slider F
float ELONG     = 1.45;
float RIM_LIT   = 0.55;   // brightness of the hole lips   [0.0 .. 1.2]
float DEPTH_DARK= 0.90;   // how dark the cavities go      [0.5 .. 1.0]
float GRAIN     = 0.09;   // micro speckle on the shell    [0.0 .. 0.25]

// --- SAME drill field as the displacement, so the tint lands exactly in the holes.
vec3 inward = normalize(pModel + vec3(1e-5));

vec3 vp = pModel * DENSITY;
vec3 vi = floor(vp);
vec3 vf = fract(vp);

float d_hole = 8.0;

for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 c = vi + g;

    vec3 p3 = fract(c * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 33.33);
    vec3 o = fract((p3.xxy + p3.yxx) * p3.zyx);
    vec3 q3 = fract((c + 17.3) * vec3(0.1031, 0.1030, 0.0973));
    q3 += dot(q3, q3.yxz + 33.33);
    vec2 re = fract((q3.xx + q3.yz) * q3.zy);
    float rr = re.x;
    float ex = re.y;

    float rad = mix(R_MIN, R_MAX, safePow(rr, SIZE_BIAS));
    rad *= step(1.0 - FILL, ex);

    vec3 r  = g + o - vf;
    vec3 rw = r - inward * dot(r, inward) * (1.0 - 1.0 / ELONG);

    d_hole = min(d_hole, length(rw) - rad);
}

d_hole /= DENSITY;

// After the CSG difference a shaded point is on the shell (d_hole > 0) or on an
// INNER WALL of a cavity (d_hole ~ 0, but the normal points inward). The two are
// told apart by the normal: on an inner wall n_model faces AWAY from 'inward'.
float facing = dot(n_model, inward);     // >0 on inner walls, <0 on the outer shell

// Wall factor: 1 deep on an inner wall, 0 on the outer surface.
float wall = smoothstep(-0.05, 0.45, facing);

// --- micro-grain on the shell.
vec3 gp = pModel * 90.0;
vec3 gi = floor(gp);
vec3 gf = gp - gi;
vec3 gw = gf * gf * (3.0 - 2.0 * gf);

float g000 = fract(sin(dot(gi + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g100 = fract(sin(dot(gi + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g010 = fract(sin(dot(gi + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g110 = fract(sin(dot(gi + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g001 = fract(sin(dot(gi + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g101 = fract(sin(dot(gi + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g011 = fract(sin(dot(gi + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
float g111 = fract(sin(dot(gi + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);

float gz0 = mix(mix(g000, g100, gw.x), mix(g010, g110, gw.x), gw.y);
float gz1 = mix(mix(g001, g101, gw.x), mix(g011, g111, gw.x), gw.y);
float grain = mix(gz0, gz1, gw.z) - 0.5;

// --- composition
vec3 col = ubuf.u_col1 * (1.0 + GRAIN * grain);

// inner walls sink toward u_col2: the deeper into the cavity, the darker.
col = mix(col, ubuf.u_col2, wall * DEPTH_DARK);

// LIP HIGHLIGHT: right at the mouth of a hole (d_hole ~ 0) the shell is thin and
// catches the light. Narrow band on the field, only on the outer side.
float lip = exp(-safePow(d_hole * DENSITY * 3.0, 2.0)) * (1.0 - wall);
col += ubuf.u_col1 * lip * RIM_LIT * 0.35;

textureCol = col;

